import * as React from 'react'
import { cn } from '@/lib/utils'

export interface DisclosureToggleProps
  extends Omit<
    React.ButtonHTMLAttributes<HTMLButtonElement>,
    'onClick' | 'children' | 'type' | 'aria-expanded' | 'aria-controls'
  > {
  /** Whether the disclosed region is currently expanded. */
  expanded: boolean
  /** Called with the next state when the toggle is activated. */
  onExpandedChange: (expanded: boolean) => void
  /** Label shown while collapsed, e.g. the translated "Show all". */
  expandLabel: string
  /** Label shown while expanded, e.g. the translated "Show fewer". */
  collapseLabel: string
  /** id of the element this toggle reveals, exposed as `aria-controls`. */
  controls?: string
}

/**
 * Text button that expands and collapses an adjacent region: caret + label,
 * `aria-expanded`, secondary text that strengthens on hover. Controlled – the
 * caller owns the expanded state, so the same toggle drives a height-capped
 * list, a "more options" tail, or an inline detail panel.
 *
 * Carries the keyboard and touch floors (`wj-focus-ring`, `.touch-target`);
 * pass `controls` whenever the revealed region can take an id.
 */
export const DisclosureToggle = React.forwardRef<HTMLButtonElement, DisclosureToggleProps>(
  function DisclosureToggle(
    { expanded, onExpandedChange, expandLabel, collapseLabel, controls, className, ...props },
    ref,
  ) {
    return (
      <button
        ref={ref}
        {...props}
        type="button"
        aria-expanded={expanded}
        aria-controls={controls}
        onClick={() => onExpandedChange(!expanded)}
        className={cn(
          'wj-focus-ring touch-target inline-flex items-center justify-center gap-1.5 rounded-lg px-3 text-sm font-medium transition-colors',
          'text-[var(--color-text-secondary-light)] dark:text-[var(--color-text-secondary-dark)]',
          'hover:text-[var(--color-text-primary-light)] dark:hover:text-[var(--color-text-primary-dark)]',
          className,
        )}
        {...props}
      >
        {/* Inline SVG caret so the design system stays icon-free (apps own that decision). */}
        <svg
          className={cn('w-4 h-4 transition-transform', expanded && 'rotate-180')}
          viewBox="0 0 16 16"
          fill="none"
          stroke="currentColor"
          strokeWidth="2"
          strokeLinecap="round"
          strokeLinejoin="round"
          aria-hidden
        >
          <path d="M3.5 6l4.5 4.5L12.5 6" />
        </svg>
        {expanded ? collapseLabel : expandLabel}
      </button>
    )
  },
)
DisclosureToggle.displayName = 'DisclosureToggle'
